// Creates a new text_input object.
pub fn (proxy &ZwpTextInputManagerV1) create_text_input() !ZwpTextInputV1 {
	id_id := proxy.conn.alloc_id()!
	id_object := wayland.Object{
		id:    id_id
		conn:  proxy.conn
		iface: 'zwp_text_input_v1'
