	proxy.conn.register_object(id_id, 'zwp_text_input_v1', &zwp_text_input_v1_desc)!
	proxy.conn.request(proxy.id, 0, [wayland.ArgValue(wayland.ObjectRef{ id: id_id })])!
	return ZwpTextInputV1{
