	version := if global.version < zwp_text_input_manager_v1_desc.version {
		global.version
	} else {
		zwp_text_input_manager_v1_desc.version
	}
	object := conn.bind_global(global, 'zwp_text_input_manager_v1', version, &zwp_text_input_manager_v1_desc)!
